#ifdef RPCS3_IOS
	// Capture the session before the copy; a completion from a previous
	// session must never appear as a producer of a new session's acquire.
	const auto label_trace = !is_get && eal < RAW_SPU_BASE_ADDR
		? rpcs3::ios::signal_trace::overlap(eal, args.size) : rpcs3::ios::signal_trace::watch_token{};
	const auto trace_dma_commit = [&]
	{
		if (label_trace)
		{
			const bool owner = _this && get_current_cpu_thread<spu_thread>() == _this;
			rpcs3::ios::signal_trace::write_event(label_trace, rpcs3::ios::signal_trace::event_kind::spu_dma_commit,
				0, get_system_time(),
				args.eal, args.size, _this ? _this->id : 0, owner ? _this->pc : 0, args.cmd);
		}
	};
#endif
